//! Repository tasks.
//!
//! `cargo run -p xtask -- vectors --check` regenerates the shared test vectors in memory and fails if they differ from
//! `spec/vectors/`. `--update` writes them. Vectors are generated by Rust and checked by both the Rust and the JS tests.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// One generated vector file: path relative to `spec/vectors/` and its exact contents.
struct VectorFile {
    name: &'static str,
    contents: String,
}

/// Every vector file. Phase 0 has only `meta.json`; later phases add one file per area.
fn vector_files() -> Vec<VectorFile> {
    let labels = ["id", "event", "vault", "public", "login", "proof", "receipt"];
    let label_list = labels
        .iter()
        .map(|p| {
            format!(
                "    {{ \"purpose\": \"{p}\", \"label\": \"{}\" }}",
                rootcard::label(p, 1)
            )
        })
        .collect::<Vec<_>>()
        .join(",\n");
    let meta = format!(
        "{{\n  \"format_version\": {},\n  \"label_prefix\": \"{}\",\n  \"labels\": [\n{}\n  ]\n}}\n",
        rootcard::FORMAT_VERSION,
        rootcard::LABEL_PREFIX,
        label_list
    );
    vec![VectorFile {
        name: "meta.json",
        contents: meta,
    }]
}

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../spec/vectors")
}

fn vectors(update: bool) -> Result<(), String> {
    let dir = vectors_dir();
    let mut stale = Vec::new();
    for file in vector_files() {
        let path = dir.join(file.name);
        let current = std::fs::read_to_string(&path).unwrap_or_default();
        if current == file.contents {
            continue;
        }
        if update {
            std::fs::write(&path, &file.contents).map_err(|e| format!("writing {}: {e}", path.display()))?;
            println!("updated {}", file.name);
        } else {
            stale.push(file.name);
        }
    }
    if stale.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "stale vectors: {} (run `cargo run -p xtask -- vectors --update` only for an intended change)",
            stale.join(", ")
        ))
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args.iter().map(String::as_str).collect::<Vec<_>>().as_slice() {
        ["vectors", "--check"] | ["vectors"] => vectors(false),
        ["vectors", "--update"] => vectors(true),
        _ => Err("usage: cargo run -p xtask -- vectors [--check | --update]".into()),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("{e}");
            ExitCode::FAILURE
        }
    }
}
